pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C("", 0, address(this)); }

    function testFuzz_property(address actor, address from, address to, uint256 id) public {
        // unminted ids and nonzero actors/recipients keep the domain wide but admissible
        vm.assume(actor != address(0));
        vm.assume(to != address(0));
        if (id < 2) id = id + 2; // keep id >= 2 but still essentially arbitrary

        // An arbitrary non-owner caller attempts to move token `id`.
        vm.prank(actor);
        bool ok;
        try c.transferFrom(from, to, id) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: a caller who is not the token's owner (and not approved) can never
        // complete a transferFrom on an unminted token — the call must revert and
        // ownership must remain unminted.
        assertTrue(!ok && c.tryOwnerOfUnminted(id) == address(0));
    }
}

