pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C("", 0, address(this)); }

    function testFuzz_property(address caller, address recipient, uint256 id) public {
        // Determine whether token `id` is currently unminted via the public view surface.
        bool minted;
        try c.ownerOf(id) returns (address owner) {
            minted = (owner != address(0));
        } catch {
            minted = false;
        }
        vm.assume(!minted); // token owned by nobody

        // An arbitrary caller attempts to move the unminted token from address(0).
        vm.prank(caller);
        bool ok;
        try c.transferFrom(address(0), recipient, id) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: an unminted token (ownerOf reverts) can never be transferred —
        // transferFrom must revert for every caller/recipient.
        assertTrue(!ok, "unminted token must not be transferable");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    FakeToken token;

    function setUp() public {
        token = new FakeToken();
        c = new C("", 0, address(this));
    }

    function testFuzz_property(address to, bool useLong) public {
        // Build a minimal long call order; maker is this test contract, which
        // supports ERC-1271 (isValidSignature below), so an empty signature verifies.
        C.Order memory order;
        order.maker = address(this);
        order.isCall = true;
        order.isLong = true;
        order.baseAsset = address(token);
        order.strike = 0;
        order.premium = 0;
        order.duration = 1;
        order.expiration = block.timestamp + 100;
        order.nonce = 0;

        bytes32 orderHash = c.hashOrder(order);
        bytes32 oppHash = c.hashOppositeOrder(order);

        uint256[] memory floors = new uint256[](0);
        c.fillOrder(order, "", floors);

        uint256 id = useLong ? uint256(orderHash) : uint256(oppHash);

        // Admissible domain: id must be owned by the caller (this contract).
        // (It is, by construction, for both ids.)

        try c.transferFrom(id, to) {
            // transfer succeeded
        } catch {
            // reference reverts when to == address(0); that is fine
        }

        // General rule: after any transferFrom, ownerOf(id) succeeds and is non-zero.
        bool ok;
        try c.ownerOf(id) returns (address o) {
            ok = (o != address(0));
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }

    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return this.isValidSignature.selector;
    }
}

contract FakeToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
